        if isinstance(demands, list):
            return [i for i in range(len(demands)) if i != depot]
        if isinstance(coords, list):
            return [i for i in range(len(coords)) if i != depot]
        return []

    customers = ids()

    def pt(i):
        if coords is None:
            return (0.0, 0.0)
        p = coords[i] if isinstance(coords, dict) else coords[i]
        return (float(p[0]), float(p[1]))

    depot_pt = pt(depot)

    def dem(i):
        if demands is None:
            return 1
        if isinstance(demands, dict):
            return int(demands.get(i, 0))
        return int(demands[i])

    cache = {}

    def dist(a, b):
        if a == b:
            return 0.0
        k = (a, b)
        if k in cache:
            return cache[k]
        pa = depot_pt if a == depot else pt(a)
        pb = depot_pt if b == depot else pt(b)
        dx = pa[0] - pb[0]
        dy = pa[1] - pb[1]
        d = (dx * dx + dy * dy) ** 0.5
        cache[k] = d
        cache[(b, a)] = d
        return d

    def route_load(r):
        s = 0
        for c in r:
            s += dem(c)
        return s

    def route_cost(r):
        if not r:
            return 0.0
        t = dist(depot, r[0])
        for i in range(len(r) - 1):
            t += dist(r[i], r[i + 1])
        return t + dist(r[-1], depot)

    def total_cost(rs):
        s = 0.0
        for r in rs:
            s += route_cost(r)
        return s

    def radial_key(i):
        x, y = pt(i)
        x -= depot_pt[0]
        y -= depot_pt[1]
        return (-(x * x + y * y), 0 if y >= 0 else 1, x / (abs(y) + abs(x) + 1e-12), i)

    customers = sorted(customers, key=radial_key)

    # Initial constructive phase: farthest-first seed, then best insertion.
    unassigned = customers[:]
    routes = []
    while unassigned:
        seed = unassigned.pop(0)
        r = [seed]
        load = dem(seed)
        improved = True
        while improved and unassigned:
            improved = False
            best = None
            best_delta = None
            for c in unassigned:
                dc = dem(c)
                if capacity and load + dc > capacity:
                    continue
                for pos in range(len(r) + 1):
                    prev = depot if pos == 0 else r[pos - 1]
                    nxt = depot if pos == len(r) else r[pos]
                    delta = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                    if best_delta is None or delta < best_delta - 1e-12 or (abs(delta - best_delta) <= 1e-12 and c < best[0]):
                        best_delta = delta
                        best = (c, pos)
            if best is not None:
                c, pos = best
                r = r[:pos] + [c] + r[pos:]
                load += dem(c)
                unassigned.remove(c)
                improved = True
        routes.append(r)

    # If capacity missing/zero, still keep feasible via single route.
    if not capacity and len(routes) > 1:
        merged = []
        for r in routes:
            merged.extend(r)
        routes = [merged]

    def two_opt(r):
        n = len(r)
        if n < 4:
            return r[:]
        best = r[:]
        best_cost = route_cost(best)
        changed = True
        while changed:
            changed = False
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    cc = route_cost(cand)
                    if cc + 1e-12 < best_cost:
                        best, best_cost = cand, cc
                        changed = True
                        break
                if changed:
                    break
        return best

    def normalize(rs):
        out = []
        for r in rs:
            if r:
                out.append(two_opt(r))
        return out

    routes = normalize(routes)

    # Local search: relocate, swap, and cross-route insertion.
    def feasible_load(r):
        return (not capacity) or route_load(r) <= capacity

    improved = True
    while improved:
        improved = False
        base = total_cost(routes)

        # relocate one customer between routes
        for a in range(len(routes)):
            if improved:
                break
            for b in range(len(routes)):
                if a == b:
                    continue
                ra = routes[a]
                rb = routes[b]
                if not ra:
                    continue
                la = route_load(ra)
                lb = route_load(rb)
                for i, c in enumerate(ra):
                    dc = dem(c)
                    if capacity and lb + dc > capacity:
                        continue
                    ra2 = ra[:i] + ra[i + 1:]
                    for pos in range(len(rb) + 1):
                        rb2 = rb[:pos] + [c] + rb[pos:]
                        cand = routes[:]
                        cand[a] = ra2
                        cand[b] = rb2
                        cand = normalize([r for r in cand if r])
                        if total_cost(cand) + 1e-12 < base:
                            routes = cand
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break

        if improved:
            continue

        # swap between routes
        for a in range(len(routes)):
            if improved:
                break
            for b in range(a + 1, len(routes)):
                ra = routes[a]
                rb = routes[b]
                if not ra or not rb:
                    continue
                la = route_load(ra)
                lb = route_load(rb)
                for i, ca in enumerate(ra):
                    dca = dem(ca)
                    for j, cb in enumerate(rb):
                        dcb = dem(cb)
                        na = la - dca + dcb
                        nb = lb - dcb + dca
                        if capacity and (na > capacity or nb > capacity):
                            continue
                        ra2 = ra[:i] + [cb] + ra[i + 1:]
                        rb2 = rb[:j] + [ca] + rb[j + 1:]
                        cand = routes[:]
                        cand[a] = ra2
                        cand[b] = rb2
                        cand = normalize([r for r in cand if r])
                        if total_cost(cand) + 1e-12 < base:
                            routes = cand
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break

        if improved:
            continue

        # move customers to merge routes when possible
        for a in range(len(routes)):
            if improved:
                break
            ra = routes[a]
            if len(ra) == 0:
                continue
            for i, c in enumerate(ra):
                dc = dem(c)
                for b in range(len(routes)):
                    if a == b:
                        continue
                    rb = routes[b]
                    if capacity and route_load(rb) + dc > capacity:
                        continue
                    ra2 = ra[:i] + ra[i + 1:]
                    best_rb = None
                    best_rb_cost = None
                    for pos in range(len(rb) + 1):
                        rb2 = rb[:pos] + [c] + rb[pos:]
                        cc = route_cost(ra2) + route_cost(rb2)
                        if best_rb_cost is None or cc < best_rb_cost - 1e-12:
                            best_rb_cost = cc
                            best_rb = rb2
                    cand = routes[:]
                    cand[a] = ra2
                    cand[b] = best_rb
                    cand = normalize([r for r in cand if r])
                    if total_cost(cand) + 1e-12 < base:
                        routes = cand
                        improved = True
                        break
                if improved:
                    break

    # Final cleanup: ensure all customers exactly once, no depot.
    seen = set()
    final_routes = []
    for r in routes:
        nr = []
        for c in r:
            if c == depot or c in seen:
                continue
            seen.add(c)
            nr.append(c)
        if nr:
            final_routes.append(nr)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        best_r = None
        best_pos = None
        best_delta = None
        dc = dem(c)
        for idx, r in enumerate(final_routes):
            if capacity and route_load(r) + dc > capacity:
                continue
            for pos in range(len(r) + 1):
                prev = depot if pos == 0 else r[pos - 1]
                nxt = depot if pos == len(r) else r[pos]
                delta = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                if best_delta is None or delta < best_delta - 1e-12:
                    best_delta = delta
                    best_r = idx
                    best_pos = pos
        if best_r is None:
            final_routes.append([c])
        else:
            final_routes[best_r] = final_routes[best_r][:best_pos] + [c] + final_routes[best_r][best_pos:]

    final_routes = [two_opt(r) for r in final_routes if r]
    return final_routes
